// E · Cockpit — "Como está o módulo agora?". Light = stored hourly series (web/data, PRE); battery/autonomy/rules = API (SIM).
// Source of truth: this .tsx file (Preact + Three.js). cockpit.js is generated by `npm --prefix web run build:ts`.
// The panels are Preact trees diffed in place on every draw(), so the crew form keeps typed values and the Artemis lander
// (Three.js, on the shared Moon scene) is a component mounted once. The Sun/Earth markers stay imperative: they are
// positioned from live layout measurements of the map marker and the panels.
import { h, Fragment, render, Component } from "../../vendor/preact/preact.module.js";
import { mountShell } from "../core/shell.js";
import { mountTerrain } from "../core/terrain.js";
import { loadSites, windowMetrics, apiWindowMetrics, api, sealFor, apiOnline } from "../core/data.js";
import { createLayerCard, statCircle, sealEl } from "../core/layers.js";
import { register, t, fmtNum, lang } from "../core/i18n.js";
import { getState, setState, onState, hrefTo } from "../core/state.js";
import type { Site } from "../core/data.js";
import type { Layer, ScenarioState } from "../core/state.js";
import type { Power, Fault, RunResult, ApiCall, Sample } from "./cockpit-model.js";
import { TEXTS } from "./cockpit-texts.js";
import { mountArtemisCockpit } from "../../moon-hd/artemis-cockpit.js";
import { CREW_DEFAULT, POWER_FIELDS, CREW_FIELDS, crewRequest, readCrewAnswer, validateInputs, sensitivityVariants, readEnergy, loadSaved, saveScenario, savedExport } from "./cockpit-crew.js";
import { foldOpen, foldSave, sessionStore, splitRules } from "./cockpit-fold.js";
import { siteEvaluateBody, FAULTS, H1_PROFILE, SPEEDS, HOUR_MS, applyFault, runScenario, nextChange, dailyFractions, autonomyHours, fmtDuration,
  clockLabel, hourIndex, evaluateRules, rulesMet, longestRun, countRises } from "./cockpit-model.js";

register(TEXTS);
const $ = <T extends HTMLElement = HTMLElement>(id: string): T => document.getElementById(id) as T;
const el = <K extends keyof HTMLElementTagNameMap>(tag: K, cls?: string | null, text?: string | null): HTMLElementTagNameMap[K] => { const e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; };
/** Mounts a DOM node built by the core (stat ring, layer card, seals) inside a Preact tree. */
function DomNode({ node }: { node: Node | null }) {
  return h("mp-node" as "span", { style: { display: "contents" }, ref: (host: HTMLElement | null) => { if (host && node && host.firstChild !== node) host.replaceChildren(node); } });
}
/** Renders a small Preact tree to a detached element, for core helpers that take a DOM node (layer card answer/why). */
function domOf(v: preact.ComponentChild): HTMLElement { const box = document.createElement("div"); render(v, box); return box.firstElementChild as HTMLElement; }
const Seal = ({ s }: { s: string }) => <span class="mp-seal" data-seal={s} title={t("seal." + s)}>{s}</span>;

const shell = mountShell({ screen: "cockpit", context: null, onLang: () => draw() });
const doc = await loadSites();
if (!doc.sites.some(s => s.id === getState().site)) setState({ site: doc.sites[0].id });
const online = await apiOnline();
const terrain = await mountTerrain($("terrain"), { sites: doc.sites, selected: getState().site, onSelect: (id: string) => setState({ site: id }) });
const narrow = () => matchMedia("(max-width:700px)").matches;
const siteNow = () => doc.sites.find(s => s.id === getState().site) as Site;
const hoursOf = () => getState().hours || 14 * 24;

/** The shared Artemis-style lander (Three.js) over this site on the shared 3D Moon, loaded on demand by the page's Moon
 * script. Renders nothing in the panel: it lives in the backdrop scene; the component owns its lifetime. */
class ArtemisLander extends Component<{ lat?: number; lon?: number; lang: string }, {}> {
  ctl: ReturnType<typeof mountArtemisCockpit> | null = null;
  componentDidMount() {
    this.ctl = mountArtemisCockpit({ lat: this.props.lat, lon: this.props.lon, texts: () => ({ note: t("cockpit.artemis_note"), tag: t("cockpit.artemis_tag") }) });
  }
  componentDidUpdate(prev: { lat?: number; lon?: number }) {
    if (!this.ctl) return;
    if (prev.lat !== this.props.lat || prev.lon !== this.props.lon) this.ctl.setSite(Number(this.props.lat), Number(this.props.lon));
    this.ctl.relabel();
  }
  componentWillUnmount() { this.ctl?.dispose(); this.ctl = null; }
  render() { return null; }
}

/** Opens the shared Moon in explore mode (focused on the lander). */
class MoonButton extends Component<{}, { na: boolean }> {
  state = { na: false };
  open(retry: boolean) {
    const live = (window as unknown as { moonBackdrop?: { explore(on: boolean): void } }).moonBackdrop;
    if (live) { live.explore(true); return; }
    const btn = document.querySelector<HTMLButtonElement>(".moon-ui .moon-open");
    if (btn && !btn.disabled) { btn.click(); return; }
    // the Moon's button is added after the page's load event: wait for it once before giving up
    if (retry) { const later = () => setTimeout(() => this.open(false), 60); if (document.readyState === "complete") later(); else addEventListener("load", later, { once: true }); return; }
    if (!btn) this.setState({ na: true });
  }
  render() {
    const na = this.state.na;
    return <button type="button" class="mp-pill mp-ck-moon" disabled={na} title={t("cockpit.moon3d.hint")} onClick={() => this.open(true)}>
      {na ? t("cockpit.moon3d.na") : "◐ " + t("cockpit.moon3d")}</button>;
  }
}

type Metrics = Awaited<ReturnType<typeof windowMetrics>>;
type Transitions = { sun?: { hours_from_start: number; kind: string } | null } | null;
type Series = Metrics["series"] & { s: { sunEl: ArrayLike<number>; earthEl: ArrayLike<number> } };
interface Light { m: Metrics; i0: number; samples: Sample[]; power: Power; f: ReturnType<typeof applyFault>; startIso: string; series: Series;
  longestDarkH: number | null; longestBlackoutH: number | null; sunrises: number | null; }
type Run = RunResult | { ok: false; offline: true; route: "none"; error?: undefined; sha?: undefined; status?: undefined; trace?: undefined };
interface Scn { t: number; playing: boolean; speed: number; fault: string | null; run: Run | null; light: Light | null; siteKey: string; dismissed: string | null;
  sky: { k: string; v: Transitions } | null; noSiteRoute: Set<string>; reportReq?: ReturnType<typeof siteEvaluateBody>; }
const S: Scn = { t: 0, playing: false, speed: SPEEDS[1], fault: null, run: null, light: null, siteKey: "", dismissed: null, sky: null, noSiteRoute: new Set() };

/** Frame the chosen site inside the free area of the map (centre on desktop, upper part above the sheet on mobile). */
function frame() {
  const site = (doc.sites.find(s => s.id === getState().site) as Site); terrain.select(site.id);
  // phone framing: core/terrain.js already centres the site in the free area between the context bar and the sheet
  placeBodies();
}
function markerCentre(): [number, number] | null {
  const b = document.querySelector(`.mp-marker[data-site="${CSS.escape(getState().site as string)}"]`); if (!b) return null;
  const r = b.getBoundingClientRect(); return [r.left + r.width / 2, r.top + r.height / 2];
}
type Body = { line: SVGLineElement; ic: HTMLElement; tag: HTMLElement };
let bodies: Record<"sun" | "earth", Body> | null = null;
function placeBodies() {
  const c = markerCentre(); if (!c || !bodies) return;
  const k = narrow() ? 0.5 : 1; const sun: number[] = [c[0] - 150 * k, c[1] - 150 * k], earth: number[] = [c[0] + 150 * k, c[1] - 170 * k];
  // Keep the Sun/Earth icon and its label below the top bar and context bar (they used to slide under them).
  const minY = Math.max(...[".mp-top", ".mp-context"].map(s => document.querySelector(s)?.getBoundingClientRect().bottom || 0)) + 22;
  sun[1] = Math.max(sun[1], minY); earth[1] = Math.max(earth[1], minY);
  // Phone: icon + label (about 60 px) must also stay above the sheet, or the label is cut by it.
  const sheetTop = document.querySelector(".mp-sheet")?.getBoundingClientRect().top;
  if (sheetTop && getComputedStyle(document.querySelector(".mp-sheet") as Element).display !== "none") { const maxY = sheetTop - 62; sun[1] = Math.min(sun[1], maxY); earth[1] = Math.min(earth[1], maxY); }
  for (const [b, p] of [["sun", sun], ["earth", earth]] as ["sun" | "earth", number[]][]) {
    Object.assign(bodies[b].ic.style, { left: p[0] + "px", top: p[1] + "px" });
    // Phone: icons sit wide of the marker and each tag is clamped on screen, so neither covers the marker "1".
    if (narrow()) p[0] = b === "sun" ? Math.max(28, c[0] - 130) : Math.min(innerWidth - 28, c[0] + 130);
    if (!narrow()) { // desktop: never behind the side panels
      const L = document.querySelector(".mp-ck-left")?.getBoundingClientRect().right || 0, R = document.querySelector(".mp-ck-right")?.getBoundingClientRect().left || innerWidth;
      p[0] = Math.min(R - 90, Math.max(L + 90, p[0]));
      if (b === "earth" && p[0] - c[0] < 120) { p[0] = Math.max(L + 90, c[0] - 170); p[1] = c[1] + 150; } } // no room on the right: below-left, clear of the marker and the Sun
    Object.assign(bodies[b].ic.style, { left: p[0] + "px", top: p[1] + "px" });
    const half = (bodies[b].tag.offsetWidth || 120) / 2, tx = narrow() ? Math.min(innerWidth - half - 8, Math.max(half + 8, p[0])) : p[0];
    Object.assign(bodies[b].tag.style, { left: tx + "px", top: p[1] + 24 + "px" });
    bodies[b].line.setAttribute("x1", String(c[0])); bodies[b].line.setAttribute("y1", String(c[1])); bodies[b].line.setAttribute("x2", String(p[0])); bodies[b].line.setAttribute("y2", String(p[1]));
  }
}
function buildBodies() {
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg"); svg.setAttribute("class", "mp-ck-lines"); svg.setAttribute("aria-hidden", "true");
  const made = {} as Record<"sun" | "earth", Body>; bodies = made;
  for (const [b, col] of [["sun", "var(--sun)"], ["earth", "var(--earth)"]] as ["sun" | "earth", string][]) {
    const line = document.createElementNS(svg.namespaceURI, "line") as SVGLineElement; line.setAttribute("stroke", col); line.setAttribute("stroke-width", "2"); line.setAttribute("stroke-dasharray", "2 7"); line.setAttribute("stroke-linecap", "round"); svg.append(line);
    const ic = el("div", "mp-bodyic"); ic.dataset.body = b; const tag = el("div", "mp-ck-tag"); tag.dataset.body = b;
    document.body.append(ic, tag); made[b] = { line, ic, tag };
  }
  document.body.append(svg);
}
buildBodies();
addEventListener("resize", () => { frame(); lightDraw(); });

let computeRevision = 0;
const scenarioKey = () => { const st = getState(); return [st.site, st.start, hoursOf(), S.fault, st.battery, st.blackout].join("|"); };
async function compute() {
  const st = { ...getState() }, site = (doc.sites.find(s => s.id === st.site) as Site), key = scenarioKey();
  if (key === S.siteKey) return true;
  const revision = ++computeRevision, hours = hoursOf(), fault = S.fault;
  const current = () => revision === computeRevision && key === scenarioKey();
  S.reportReq = undefined;
  S.siteKey = "";
  const m = await apiWindowMetrics(doc, site, st.start, hours);
  if (!current()) return false;
  const series = m.series, i0 = Math.ceil((m.t0 - series.start) / HOUR_MS);
  const base = { power: { ...H1_PROFILE }, samples: [], delayH: 0 };
  const win = (off: number, n: number) => Array.from({ length: Math.max(0, Math.min(n, series.count - i0 - off)) }, (_, h) => ({ sun_visible: series.sunMargin[i0 + off + h] >= 0, earth_visible: series.earthMargin[i0 + off + h] >= 0 }));
  const f = applyFault(fault, { ...base, samples: win(0, hours) });
  const samples = win(f.delayH, hours).map(x => f.fault?.noEarth ? { ...x, earth_visible: false } : x);
  const power = { ...f.power, reserve_wh: f.power.battery_capacity_wh * st.battery / 100 };
  const startIso = new Date(m.t0 + f.delayH * HOUR_MS).toISOString();
  let run: Run;
  let reportReq: Scn["reportReq"];
  if (!online) run = { ok: false, offline: true, route: "none" };
  else {
    const call = ((p: string, o?: { method?: string; body?: unknown }) => (p === "/api/onboard/site-evaluate" && S.noSiteRoute.has(st.site as string)) ? Promise.resolve({ ok: false, error: "cached DATA_NOT_AVAILABLE" }) : api(p, o)) as unknown as ApiCall;
    reportReq = siteEvaluateBody({ siteId: st.site as string, startIso: new Date(m.t0).toISOString(), hours: hours, power, maxBlackoutH: Math.min(st.blackout, hours), delayH: f.delayH });
    run = await runScenario(call, { siteId: st.site as string, startIso: new Date(m.t0).toISOString(), hours: hours, power, maxBlackoutH: Math.min(st.blackout, hours), samples, delayH: f.delayH });
    if (!current()) return false;
    if (run.route === "eval") S.noSiteRoute.add(st.site as string);
    if (run.route === "site") (run as { samples?: unknown }).samples = null;
  }
  if (!current()) return false;
  S.reportReq = reportReq;
  S.siteKey = key;
  S.light = { m, i0, samples, power, f, startIso, series: series as Series,
    longestDarkH: samples.length ? longestRun(samples, "sun_visible", false) : null,
    longestBlackoutH: samples.length ? longestRun(samples, "earth_visible", false) : null, sunrises: samples.length ? countRises(samples) : null };
  S.run = run; S.t = Math.min(S.t, hours);
  return true;
}

async function skyTransition(site: Site, atIso: string): Promise<Transitions> {
  const k = site.id + atIso; if (S.sky?.k === k) return S.sky.v;
  const r = await api(`/api/sites/${encodeURIComponent(site.id)}/sky?start=${encodeURIComponent(atIso)}&hours=240`, { timeoutMs: 3000 });
  const v = r.ok ? (r.data as { next_transitions: Transitions }).next_transitions : null; S.sky = { k, v }; return v;
}

// ---- Panel components (Preact) ----

// Secondary cards are accordions (<details>/<summary>), closed by default; the choice is remembered for this tab session.
// `open` is passed on every render but only changes when the saved state does, so Preact never fights the user's toggle.
const foldStore = sessionStore();
function Accordion({ id, cls, name, seal, children }: { id: string; cls: string; name: string; seal: string; children?: preact.ComponentChildren }) {
  return <details class={"ck-acc " + cls} id={"acc-" + id} open={foldOpen(foldStore, id)}
    onToggle={(e: Event) => { foldSave(foldStore, id, (e.currentTarget as HTMLDetailsElement).open); if (!narrow()) placeBodies(); }}>
    <summary class="ck-acc-sum"><span class="ck-acc-name">{name}</span><Seal s={seal} /></summary>
    {children}
  </details>;
}
const accordion = (id: string, cls: string, name: string, seal: string, body: preact.ComponentChildren) => <Accordion id={id} cls={cls} name={name} seal={seal}>{body}</Accordion>;
let rulesOpen = foldOpen(foldStore, "rules-more");

type Next = { visible?: boolean; inHours?: number | null; lastsHours?: number | null } | null | undefined;
function Vis({ body, next, elev }: { body: "sun" | "earth"; next: Next; elev: number | null }) {
  return <div class="mp-vis" data-body={body} data-vis={next?.visible ? "yes" : "no"}>
    <span><span class="dot"></span>{t(body === "sun" ? "cockpit.sun_visible" : "cockpit.earth_visible")}</span>
    <b>{elev == null ? t("nd") : t(next?.visible ? "cockpit.yes_angle" : "cockpit.sun_no", { n: fmtNum(elev, 1) })}</b>
  </div>;
}

function SunDays({ days, today, nightLine }: { days: (number | null)[]; today: number; nightLine: string }) {
  return <div>
    <div class="mp-days" role="img" aria-label={t("cockpit.sun_hours_day")}>
      {days.map((f, d) => <i data-nd={f == null ? "1" : undefined} data-today={d === today ? "1" : undefined} style={f == null ? undefined : { "--f": Math.round(f * 100) + "%" }}></i>)}
    </div>
    <div class="mp-axis"><span>D0</span><em>{t("cockpit.today")}</em><span>{"D" + (days.length - 1)}</span></div>
    <p class="mp-label">{nightLine}</p>
  </div>;
}

type RuleRow = ReturnType<typeof evaluateRules>[number];
function RulesCard({ list, lim }: { list: RuleRow[]; lim: Record<string, number> }) {
  const met = rulesMet(list);
  const row = (r: RuleRow) => <div class="mp-rule" data-status={r.status} data-rule={r.id}>
    <span>{t("cockpit.rule." + r.id, { n: lim[r.id] ?? "" })}<small>{r.id !== "cold" ? `${t("cockpit.assumed")} · ${r.seal}` : t("cockpit.cold_nd")}</small></span>
    <span class="st">{t(r.status === "pass" ? "cockpit.pass" : r.status === "risk" ? "cockpit.risk" : "cockpit.nodata")}</span>
  </div>;
  // first 3 rules in view; the others open in place behind "+N rules" (the "x of y met" count above always covers all of them)
  const { head, more } = splitRules(list);
  return <article class="mp-card mp-rules">
    <div class="mp-head"><h3>{t("cockpit.rules")}</h3><span class="mp-count">{t("cockpit.rules_met", { n: met.ok, m: met.of })}</span></div>
    {head.map(row)}
    <div class="mp-rules-more" id="rules-more" hidden={!rulesOpen}>{more.map(row)}</div>
    <button type="button" class="mp-link ck-rules-toggle" aria-controls="rules-more" aria-expanded={rulesOpen} hidden={!more.length}
      onClick={() => { rulesOpen = !rulesOpen; foldSave(foldStore, "rules-more", rulesOpen); draw(); }}>
      {t(rulesOpen ? "cockpit.rules_less" : "cockpit.rules_more", { n: more.length })}</button>
    <a class="mp-link" href={hrefTo("evidence.html")}>{t("cockpit.where_rules")}</a>
  </article>;
}

interface AlertInfo { key: string; setting: boolean | undefined; inH: number | null | undefined; nightH: number | null | undefined; fromApi: boolean }
function AlertCard({ a }: { a: AlertInfo }) {
  const hidden = a.inH == null || S.dismissed === a.key;
  return <article class="mp-card mp-alert" hidden={hidden}>
    {!hidden && <>
      <span class="mp-alert-ic"></span>
      <div class="mp-alert-body">
        <h3>{t(a.setting ? "cockpit.sunset_in" : "cockpit.alert_title_rise", { t: fmtDuration(a.inH as number) })}</h3>
        {a.nightH != null && <p>{t(a.setting ? "cockpit.sunset_tip" : "cockpit.alert_tip_rise", { n: fmtNum(a.nightH) })}</p>}
        <div class="mp-alert-act">
          <button type="button" class="mp-pill is-white" onClick={() => { S.dismissed = a.key; draw(); }}>{t("cockpit.got_it")}</button>
          <p class="mp-label">{t(a.fromApi ? "cockpit.alert_src_api" : "cockpit.alert_src_series")}</p>
        </div>
      </div>
    </>}
  </article>;
}

function FaultCard({ run }: { run: Run | null }) {
  return accordion("faults", "mp-glass", t("cockpit.test_problem"), "SIM",
    <div class="mp-faults">
      {Object.values(FAULTS).map(f => <button type="button" class="mp-pill" data-fault={f.id} aria-pressed={S.fault === f.id}
        onClick={() => { S.fault = S.fault === f.id ? null : f.id; draw(); }}>{t(f.key, { n: f.n })}</button>)}
      <p class="mp-ck-note">{run?.ok ? "" : t(run?.offline ? "cockpit.offline" : "cockpit.route.none")}</p>
    </div>);
}

// Crew, consumables and power (legacy onboard "Entrada" + "Vida", now on the real API: POST /api/onboard/site-evaluate).
// Inputs are uncontrolled: the component is never remounted between draws, so typed values survive redraws.
type Table = { head: string[]; rows: string[][]; foot?: string };
interface CrewState { out: string | Table; sens: string | Table; savedMsg: string; errors: string[]; running: boolean; sensing: boolean; saved: ReturnType<typeof loadSaved> }
const store = (() => { try { return globalThis.localStorage; } catch { return null; } })();
function TableOut({ v }: { v: string | Table }) {
  if (typeof v === "string") return <>{v}</>;
  return <>
    <DomNode node={sealEl("SIM")} />
    <table class="ck-crew-table"><thead><tr>{v.head.map(x => <th>{x}</th>)}</tr></thead>
      <tbody>{v.rows.map(r => <tr>{r.map(x => <td>{x}</td>)}</tr>)}</tbody></table>
    {v.foot != null && <p class="mp-label">{v.foot}</p>}
  </>;
}
class CrewCard extends Component<{}, CrewState> {
  state: CrewState = { out: "", sens: "", savedMsg: "", errors: [], running: false, sensing: false, saved: loadSaved(store) };
  form: HTMLFormElement | null = null;
  read() {
    const elems = this.form!.elements as unknown as Record<string, HTMLInputElement>, v = (k: string) => Number(elems[k].value);
    return { power: Object.fromEntries(POWER_FIELDS.map(k => [k, v(k)])), crew: { ...CREW_DEFAULT, ...Object.fromEntries(CREW_FIELDS.map(k => [k, v(k)])) } };
  }
  fill(e: { power?: Record<string, number>; crew?: Record<string, number> }) {
    const elems = this.form!.elements as unknown as Record<string, HTMLInputElement>;
    for (const k of POWER_FIELDS) if (e.power?.[k] != null) elems[k].value = String(e.power[k]);
    for (const k of CREW_FIELDS) if (e.crew?.[k] != null) elems[k].value = String(e.crew[k]);
  }
  body(q: NonNullable<Scn["reportReq"]>, power: Record<string, number>, crew: Record<string, unknown>) {
    return crewRequest({ siteId: q.candidates[0].site_id, startIso: q.start_utc, hours: q.duration_hours, maxBlackoutH: q.max_comm_blackout_hours, delayH: q.candidates[0].delay_hours, power, crew: crew as typeof CREW_DEFAULT });
  }
  async run(e: Event) {
    e.preventDefault();
    const { power, crew } = this.read(), chk = validateInputs(power, crew);
    this.setState({ errors: chk.errors });
    if (!chk.ok) { this.setState({ out: t("crew.invalid") }); return; }
    const q = S.reportReq; if (!q) { this.setState({ out: t("cockpit.report.offline") }); return; }
    this.setState({ running: true, out: t("crew.wait") });
    const r = await api("/api/onboard/site-evaluate", { method: "POST", body: this.body(q, power, crew), timeoutMs: 15000 });
    if (!r.ok) { this.setState({ running: false, out: t("cockpit.report.fail", { e: r.error }) }); return; }
    const a = readCrewAnswer(r.data);
    this.setState({ running: false, out: { head: ["crew.h.res", "crew.h.aut", "crew.h.mar", "crew.h.st"].map(x => t(x)),
      rows: a.rows.map(row => [t("crew.res." + row.resource), row.autonomyH == null ? t("nd") : fmtNum(row.autonomyH, 0) + " h", row.marginH == null ? t("nd") : fmtNum(row.marginH, 0) + " h", row.status || t("nd")]),
      foot: t("crew.decision", { d: a.decision || t("nd") }) } });
  }
  async sensitivity() {
    const { power, crew } = this.read(), chk = validateInputs(power, crew);
    if (!chk.ok) { this.setState({ sens: t("crew.invalid") }); return; }
    const q = S.reportReq; if (!q) { this.setState({ sens: t("cockpit.report.offline") }); return; }
    this.setState({ sensing: true, sens: t("crew.wait") });
    const rows: string[][] = [], wh = (x: number | null | undefined) => x == null ? t("nd") : fmtNum(x, 0) + " Wh";
    for (const v of sensitivityVariants(power)) {
      const r = await api("/api/onboard/site-evaluate", { method: "POST", body: this.body(q, v.power, crew), timeoutMs: 15000 });
      const e = r.ok ? readEnergy(r.data) : null;
      rows.push([t("crew.s." + v.id), wh(e?.minWh), wh(e?.unservedWh), r.ok ? (e?.endMode || t("nd")) : String(r.error)]);
    }
    this.setState({ sensing: false, sens: { head: ["crew.s.case", "crew.s.min", "crew.s.unserved", "crew.s.end"].map(x => t(x)), rows } });
  }
  save() {
    const { power, crew } = this.read(), now = new Date(), q = S.reportReq;
    const label = `${q ? q.candidates[0].site_id : t("nd")} · ${q ? (q.start_utc as string).slice(0, 10) : ""} · ${now.toISOString().slice(0, 16).replace("T", " ")} UTC`;
    const r = saveScenario(store, { id: now.toISOString(), label, query: location.search, power, crew });
    this.setState({ savedMsg: r.ok ? t("crew.saved") : t("crew.saveFail"), saved: loadSaved(store) });
  }
  exportAll() {
    const url = URL.createObjectURL(new Blob([JSON.stringify(savedExport(loadSaved(store)), null, 2)], { type: "application/json" }));
    const a = Object.assign(document.createElement("a"), { href: url, download: "cockpit-scenarios.json" }); a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
  render() {
    const s = this.state, defaults: Record<string, unknown> = { ...H1_PROFILE, reserve_wh: 4000, ...CREW_DEFAULT };
    const field = (k: string, step: string) => <label>{t("crew.f." + k)}
      <input type="number" min="0" step={step} name={k} inputMode="decimal" defaultValue={String(defaults[k])} aria-invalid={s.errors.length ? s.errors.includes(k) : undefined} /></label>;
    return <details class="mp-card ck-crew ck-acc" id="acc-crew" open={foldOpen(foldStore, "crew")}
      onToggle={(e: Event) => foldSave(foldStore, "crew", (e.currentTarget as HTMLDetailsElement).open)}>
      <summary class="ck-crew-title ck-acc-sum">{t("crew.title")}</summary>
      <form class="ck-crew-form" noValidate ref={(f: HTMLFormElement | null) => { this.form = f; }} onSubmit={(e: Event) => this.run(e)}>
        {POWER_FIELDS.map(k => field(k, "1"))}
        {CREW_FIELDS.map(k => field(k, k === "size" ? "1" : "0.01"))}
        <button type="submit" class="mp-pill is-primary" disabled={s.running}>{t("crew.run")}</button>
      </form>
      <div class="ck-crew-out" aria-live="polite"><TableOut v={s.out} /></div>
      <div class="ck-crew-tools">
        <button type="button" class="mp-pill" disabled={s.sensing} onClick={() => this.sensitivity()}>{t("crew.sens")}</button>
        <button type="button" class="mp-pill" onClick={() => this.save()}>{t("crew.save")}</button>
        <button type="button" class="mp-pill" onClick={() => this.exportAll()}>{t("crew.export")}</button>
      </div>
      <div class="ck-crew-out" aria-live="polite"><TableOut v={s.sens} /></div>
      <p class="mp-label" aria-live="polite">{s.savedMsg}</p>
      <ul class="ck-saved">{s.saved.map(e => <li><button type="button" class="mp-link"
        onClick={() => { this.fill(e); if (e.query && e.query !== location.search) location.search = e.query; }}>{e.label}</button></li>)}</ul>
      <p class="mp-label">{t("crew.src", { s: CREW_DEFAULT.rate_source })}</p>
    </details>;
  }
}

const left = $("left"), right = $("right");
const sheet = $("sheet");

// Every caller fires draw() without awaiting it: a failed series fetch (offline, or cancelled by navigation)
// must not become an unhandled rejection. Show it, and clear the cache key so the next draw retries.
function draw(): Promise<void> {
  return drawNow().then(() => { document.querySelector(".mp-ck-loaderr")?.remove(); }, (err: unknown) => {
    S.siteKey = "";
    let note = document.querySelector<HTMLElement>(".mp-ck-loaderr");
    if (!note) { note = el("p", "mp-ck-loaderr mp-glass"); note.setAttribute("role", "status"); document.body.append(note); }
    note.textContent = t("cockpit.load_failed");
    note.dataset.error = String((err as Error)?.message || err);
  });
}
async function drawNow() {
  if (!await compute()) return;
  const drawKey = scenarioKey();
  const th = hourIndex(S.t, hoursOf()); // series and API trace are hourly: read them at a whole hour, keep S.t continuous
  const st = getState(), site = (doc.sites.find(s => s.id === st.site) as Site), L = S.light as Light, run = S.run, series = L.series, H = hoursOf();
  const i = L.i0 + th, trace = run?.ok ? run.trace : null, cap = L.power.battery_capacity_wh;
  const charge = trace ? trace[Math.min(th, trace.length - 1)] : null;
  const floorWh = cap * st.battery / 100;
  const sunNext = nextChange(series.sunMargin, i, series.count), earthNext = nextChange(series.earthMargin, i, series.count);
  const nightH = sunNext?.visible ? sunNext.lastsHours : sunNext?.inHours; // next night length (or what is left of the current one)
  const auto = autonomyHours(charge as number, floorWh, L.power.load_w);
  const margin = auto != null && nightH != null ? auto - nightH : null;
  const hh = (v: number | null | undefined, d = 0, sign = false) => v == null ? t("nd") : (sign && v > 0 ? "+" : "") + fmtNum(v, d) + "h";
  const clock = clockLabel(L.m.t0 + L.f.delayH * HOUR_MS, th);
  const seal = "SIM";

  shell.setContext({ site: t("cockpit.simulated_operation", { site: `${site.n} · ${site.name}` }),
    date: `${t("cockpit.day_time", { n: clock.day, h: clock.hhmm })} UTC`, days: fmtNum(H / 24), seal, online });
  const ctxEl = document.querySelector(".mp-context");
  if (ctxEl) { const chip = el("span", "mp-sim-chip", t("cockpit.sim_label")); ctxEl.append(el("span", "mp-label", t("cockpit.profile")), chip); }

  // left panel: battery ring, Sun/Earth now, 3D Moon, daily sunlight card, and the Three.js lander
  const stat = statCircle({ value: charge == null ? t("nd") : fmtNum(100 * charge / cap) + "%", label: t("cockpit.battery"), seal: charge == null ? "N/D" : seal,
    satellites: [{ value: hh(nightH), label: t("cockpit.next_night") }, { value: hh(auto), label: t("cockpit.endurance") },
      { value: hh(margin, 0, true), label: t("cockpit.margin") }, { value: fmtNum(st.battery) + "%", label: t("cockpit.floor") }] });
  const sunEl = Number.isFinite(series.s.sunEl[i]) ? series.s.sunEl[i] : null, earthEl = Number.isFinite(series.s.earthEl[i]) ? series.s.earthEl[i] : null;
  const earthSeen = L.f.fault?.noEarth ? { ...earthNext, visible: false } : earthNext;
  const days = dailyFractions(series.sunMargin, L.i0, H), today = Math.floor(th / 24);
  const nightLine = nightH == null ? t("nd") : t("cockpit.next_night_line", { t: sunNext!.visible ? fmtDuration(sunNext!.inHours as number) : t("nd"), n: fmtNum(nightH) });
  const rows = (...a: [string, unknown][]) => a.map(([k, v]) => [k, v ?? t("nd")]);
  const code = (v: unknown) => domOf(<code class="mp-coord">{String(v ?? t("nd"))}</code>);
  const route = run?.ok ? t(run.route === "site" ? "cockpit.route.site" : "cockpit.route.eval") : t("cockpit.route.none");
  const card = createLayerCard({ id: "card-sun-days", title: t("cockpit.sun_hours_day"), status: L.m.sunPct.status, answer: domOf(<SunDays days={days} today={today} nightLine={nightLine} />),
    why: domOf(<p class="mp-label">{t("cockpit.sunsets_why") + " " + t("cockpit.nextnight_why")}</p>), layer: st.layer, onLayer: (layer: Layer) => setState({ layer }),
    proof: rows([t("proof.source"), `${L.m.sunPct.source}`], [t("proof.sha"), code(L.m.sunPct.detail.sha256)], [t("proof.window"), `${L.m.sunPct.detail.start} · ${fmtNum(H)} h`],
      [t("proof.status"), `${L.m.sunPct.status} · ${t("seal." + L.m.sunPct.seal)}`], [t("cockpit.route"), route],
      [t("cockpit.inputs"), `${t("cockpit.in.capacity")} ${fmtNum(L.power.battery_capacity_wh)} Wh · ${t("cockpit.in.initial")} ${fmtNum(L.power.initial_charge_wh)} Wh · ${t("cockpit.in.solar")} ${fmtNum(L.power.solar_generation_w)} W · ${t("cockpit.in.load")} ${fmtNum(L.power.load_w)} W · ${t("cockpit.in.floor")} ${fmtNum(st.battery)}%`],
      [t("cockpit.fault_on", { p: "" }), L.f.fault ? `${t(L.f.fault.key, { n: L.f.fault.n })} (${t("seal.SIM")})` : t("nd")],
      [t("proof.status") + " API", run?.ok ? `${run.status} · ${t("seal." + sealFor(run.status))}` : t("cockpit.route.none")], ["inputs_sha256", code((run as { sha?: string } | null)?.sha)],
      [t("cockpit.derived"), trace ? "charge_wh" : t("nd")]) });
  const cur = siteNow();
  render(<>
    <p class="mp-ck-title">{t("cockpit.how_now")}</p>
    <DomNode node={stat} />
    <div class="mp-visrow"><Vis body="sun" next={sunNext} elev={sunEl} /><Vis body="earth" next={earthSeen} elev={earthEl} /></div>
    <MoonButton />
    {accordion("sun-days", "ck-acc-sun", t("cockpit.sun_hours_day"), sealFor(L.m.sunPct.status), <DomNode node={card.el} />)}
    <ArtemisLander lat={cur?.lat} lon={cur?.lon} lang={lang()} />
  </>, left);

  // right panel: rules, next sunset/sunrise alert, fault injection, crew and consumables
  const list = evaluateRules({ rules: { night: st.night, blackout: st.blackout, battery: st.battery }, lightStatus: doc.status, trace, capacityWh: run?.ok ? cap : null, light: L });
  const lim: Record<string, number> = { floor: st.battery, night: st.night, blackout: st.blackout, days: 5, sunrises: 2 };
  // alert: next sunset from the API's next_transitions when it has the site's series, else from the stored series
  const at = new Date(L.m.t0 + L.f.delayH * HOUR_MS + th * HOUR_MS).toISOString();
  let apiTr = online ? await skyTransition(site, at) : null;
  if (drawKey !== scenarioKey()) return;
  const apiSun = apiTr?.sun || null;
  const fromApi = !!apiSun && Number.isFinite(apiSun.hours_from_start);
  const inH = fromApi ? apiSun.hours_from_start : sunNext?.inHours, setting = fromApi ? apiSun.kind === "sunset" : sunNext?.visible;
  const alert: AlertInfo = { key: `${site.id}|${setting}|${Math.round((i + (inH ?? 0)))}`, setting, inH, nightH, fromApi };
  render(<>
    <RulesCard list={list} lim={lim} />
    <AlertCard a={alert} />
    <FaultCard run={run} />
    <CrewCard />
  </>, right);

  // map tags
  const tagSun = sunNext?.inHours != null ? t(sunNext.visible ? "cockpit.sun_sets_in" : "cockpit.sun_rises_in", { t: fmtDuration(sunNext.inHours) }) : t("nd");
  const tagEarth = L.f.fault?.noEarth ? t("cockpit.problem_no_antenna") : earthNext?.inHours != null ? t(earthNext.visible ? "cockpit.earth_gone_in" : "cockpit.earth_back_in", { t: fmtDuration(earthNext.inHours) }) : t("nd");
  bodies!.sun.tag.textContent = tagSun; bodies!.earth.tag.textContent = tagEarth; placeBodies();
  // player
  const rg = $<HTMLInputElement>("range"); rg.max = String(H); rg.value = String(th); rg.style.setProperty("--p", String(H ? th / H : 0)); rg.setAttribute("aria-valuetext", clock.text);
  $("time").textContent = clock.text; $("end").textContent = "D" + fmtNum(H / 24);
  $("play").textContent = S.playing ? "⏸" : "▶"; $("play").setAttribute("aria-label", t(S.playing ? "cockpit.pause" : "cockpit.play"));
  $("restart").setAttribute("aria-label", t("cockpit.restart")); $("speed").setAttribute("aria-label", t("cockpit.speed")); rg.setAttribute("aria-label", t("cockpit.time"));
  // Printable site report from the onboard computer API (was only in the legacy onboard panel).
  const rep = $<HTMLButtonElement>("report"); rep.textContent = t("cockpit.report"); rep.disabled = !S.reportReq; rep.title = S.reportReq ? t("cockpit.report.hint") : t("cockpit.report.offline");
  $("handle").setAttribute("aria-label", t("cockpit.sheet"));
}

// player
const rg = $<HTMLInputElement>("range"), sp = $<HTMLSelectElement>("speed");
for (const v of SPEEDS) sp.append(new Option(`${v} h/s`, String(v), false, v === S.speed));
sp.onchange = () => { S.speed = Number(sp.value); };
let timer: ReturnType<typeof setInterval> | null = null;
function setPlaying(p: boolean) { S.playing = p; clearInterval(timer as ReturnType<typeof setInterval>); if (p) timer = setInterval(() => { if (S.t >= hoursOf()) { setPlaying(false); return; } S.t = Math.min(hoursOf(), S.t + S.speed / 10); lightDraw(); }, 100); draw(); }
let busy = false; async function lightDraw() { if (busy) return; busy = true; try { await draw(); } finally { busy = false; } }
$("play").onclick = () => setPlaying(!S.playing);
$("restart").onclick = () => { S.t = 0; setPlaying(false); };
rg.oninput = () => { S.t = Number(rg.value); lightDraw(); };
$("player").addEventListener("keydown", e => { if (e.key === " " && e.target === rg) { e.preventDefault(); setPlaying(!S.playing); } });
// bottom sheet (mobile): drag the handle
{ const hd = $("handle"); let y0: number | null = null, h0 = 0;
  hd.addEventListener("pointerdown", e => { y0 = e.clientY; h0 = sheet.getBoundingClientRect().height; hd.setPointerCapture(e.pointerId); });
  hd.addEventListener("pointermove", e => { if (y0 == null) return; sheet.style.setProperty("--sheet-h", Math.max(96, Math.min(innerHeight * 0.78, h0 + (y0 - e.clientY))) + "px"); });
  hd.addEventListener("pointerup", () => { y0 = null; });
  hd.addEventListener("keydown", e => { const c = sheet.getBoundingClientRect().height; if (e.key === "ArrowUp") sheet.style.setProperty("--sheet-h", Math.min(innerHeight * 0.78, c + 40) + "px"); if (e.key === "ArrowDown") sheet.style.setProperty("--sheet-h", Math.max(96, c - 40) + "px"); }); }
let last = getState().site;
onState((s: ScenarioState) => { if (s.site !== last) { last = s.site; S.t = 0; S.dismissed = null; frame(); } draw(); });
frame(); await draw(); frame();
(globalThis as unknown as Record<string, unknown>).__cockpit = S;

// Opens the API's printable HTML report for the current scenario (POST /api/onboard/site-report).
document.getElementById("report")?.addEventListener("click", async e => {
  const b = e.currentTarget as HTMLButtonElement; if (!S.reportReq) return;
  b.disabled = true; const r = await api("/api/onboard/site-report", { method: "POST", body: S.reportReq, as: "text", timeoutMs: 15000 }); b.disabled = false;
  if (!r.ok) { b.title = t("cockpit.report.fail", { e: r.error }); b.textContent = t("cockpit.report.failShort"); return; }
  window.open(URL.createObjectURL(new Blob([r.data as string], { type: "text/html" })), "_blank", "noopener");
});
